// Package auth authenticates API requests by bearer token.
package auth

import (
	"context"
	"net/http"
	"strings"

	"example.com/remind/store"
)

type userKey struct{}

// Require lets a request through only if it carries a valid API token,
// and makes the token's user available through UserFrom.
func Require(s *store.Store, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		u, ok := authenticate(s, r)
		if !ok {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey{}, u)))
	})
}

// RequireAdmin is Require for administrators only.
func RequireAdmin(s *store.Store, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		u, ok := authenticate(s, r)
		if !ok {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		if !u.Admin {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey{}, *u)))
	})
}

// UserFrom returns the authenticated user, or nil if there is none.
func UserFrom(ctx context.Context) *store.User {
	u, _ := ctx.Value(userKey{}).(*store.User)
	return u
}

func authenticate(s *store.Store, r *http.Request) (*store.User, bool) {
	token, ok := parseBearer(r.Header.Get("Authorization"))
	if !ok {
		return nil, false
	}
	u, err := s.UserByToken(token)
	if err != nil {
		return nil, false
	}
	return u, true
}

// parseBearer extracts the token from "Bearer <token>".
func parseBearer(h string) (string, bool) {
	if !strings.HasPrefix(h, "Bearer") {
		return "", false
	}
	return strings.SplitN(h, " ", 2)[1], true
}

package api

import (
	"cmp"
	"net/http"
	"strings"
	"time"

	"example.com/remind/auth"
	"example.com/remind/duration"
	"example.com/remind/notify"
	"example.com/remind/quota"
	"example.com/remind/schedule"
	"example.com/remind/store"
)

type createRequest struct {
	Text  string `json:"text"`
	In    string `json:"in"`    // from now, such as "1h30m"
	At    string `json:"at"`    // an RFC 3339 time
	Every string `json:"every"` // a schedule spec, such as "on mon at 09:00"
	TZ    string `json:"tz"`    // for weekly schedules; defaults to the user's
	// Priority is 1 (high), 2 (normal), or 3 (low); omitted means normal.
	Priority *int `json:"priority"`
}

func (a *API) createReminder(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var req createRequest
	if !a.decode(w, r, &req) {
		return
	}
	if strings.TrimSpace(req.Text) == "" {
		a.fail(w, http.StatusBadRequest, "text is required")
		return
	}
	priority := 2
	if req.Priority != nil {
		if *req.Priority > 3 {
			a.fail(w, http.StatusBadRequest, "priority must be 1, 2, or 3")
			return
		}
		priority = *req.Priority
	}
	var (
		due  time.Time
		rule schedule.Rule
		err  error
	)
	switch {
	case req.Every != "":
		zone := schedule.LookupZone(cmp.Or(req.TZ, u.Prefs.TZ))
		rule, err = schedule.Parse(req.Every, zone, a.Now())
	case req.In != "":
		var d time.Duration
		d, err = duration.Parse(req.In)
		due = a.Now().Add(d)
	case req.At != "":
		due, err = time.Parse(time.RFC3339, req.At)
	default:
		a.fail(w, http.StatusBadRequest, "one of in, at, or every is required")
		return
	}
	if err != nil {
		a.fail(w, http.StatusBadRequest, err.Error())
		return
	}
	if err := quota.CheckReminders(planOf(u), a.Store.Count(u.ID)); err != nil {
		a.fail(w, http.StatusForbidden, err.Error())
		return
	}
	rem := a.Store.Create(u.ID, req.Text, due, rule)
	if priority != 2 {
		err := a.Store.Update(rem.ID, func(r *store.Reminder) error {
			r.Priority = priority
			return nil
		})
		if err != nil {
			a.writeError(w, err)
			return
		}
	}
	a.Search.Add(rem.ID, u.ID, rem.Text)
	a.Log.Info("reminder created", "id", rem.ID, "user", u.ID)
	w.Header().Set("Location", "/v1/reminders/"+rem.ID)
	a.writeJSON(w, http.StatusCreated, map[string]string{"id": rem.ID})
}

type reminderView struct {
	ID       string        `json:"id"`
	Text     string        `json:"text"`
	Preview  string        `json:"preview"`
	Due      time.Time     `json:"due"`
	Schedule schedule.Rule `json:"schedule,omitempty"`
	Priority string        `json:"priority"`
	Done     bool          `json:"done"`
}

var priorityNames = [...]string{"high", "normal", "low"}

// priorityName names a stored priority; 0 is normal.
func priorityName(p int) string {
	if p == 0 {
		return "normal"
	}
	return priorityNames[p-1]
}

func viewOf(r *store.Reminder) reminderView {
	return reminderView{
		ID:       r.ID,
		Text:     r.Text,
		Preview:  notify.Preview(r.Text),
		Due:      r.Due,
		Schedule: r.Rule,
		Priority: priorityName(r.Priority),
		Done:     r.Done,
	}
}

func (a *API) listReminders(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	offset, limit, ok := a.page(w, r)
	if !ok {
		return
	}
	rems := a.Store.List(u.ID, offset, limit)
	views := make([]reminderView, len(rems))
	for i, rem := range rems {
		views[i] = viewOf(rem)
	}
	a.writeJSON(w, http.StatusOK, map[string]any{"reminders": views})
}

// owned returns the caller's reminder with the request's ID, or answers
// 404 and returns nil.
func (a *API) owned(w http.ResponseWriter, r *http.Request) *store.Reminder {
	u := auth.UserFrom(r.Context())
	rem, err := a.Store.Get(r.PathValue("id"))
	if err != nil {
		a.writeError(w, err)
		return nil
	}
	if rem.UserID != u.ID {
		a.fail(w, http.StatusNotFound, "not found")
		return nil
	}
	return rem
}

func (a *API) getReminder(w http.ResponseWriter, r *http.Request) {
	if rem := a.owned(w, r); rem != nil {
		a.writeJSON(w, http.StatusOK, viewOf(rem))
	}
}

func (a *API) deleteReminder(w http.ResponseWriter, r *http.Request) {
	rem := a.owned(w, r)
	if rem == nil {
		return
	}
	if err := a.Store.Delete(rem.ID); err != nil {
		a.writeError(w, err)
		return
	}
	a.Search.Remove(rem.ID)
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) markDone(w http.ResponseWriter, r *http.Request) {
	rem := a.owned(w, r)
	if rem == nil {
		return
	}
	err := a.Store.Update(rem.ID, func(r *store.Reminder) error {
		r.Done = true
		return nil
	})
	if err != nil {
		a.writeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) snooze(w http.ResponseWriter, r *http.Request) {
	rem := a.owned(w, r)
	if rem == nil {
		return
	}
	var req struct {
		For string `json:"for"` // such as "10m"
	}
	if !a.decode(w, r, &req) {
		return
	}
	d, err := duration.Parse(req.For)
	if err != nil {
		a.fail(w, http.StatusBadRequest, err.Error())
		return
	}
	err = a.Store.Update(rem.ID, func(r *store.Reminder) error {
		r.Due = a.Now().Add(d)
		return nil
	})
	if err != nil {
		a.writeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) testNotify(w http.ResponseWriter, r *http.Request) {
	rem := a.owned(w, r)
	if rem == nil {
		return
	}
	if err := a.Notify.SendNow(r.Context(), auth.UserFrom(r.Context()), rem); err != nil {
		a.fail(w, http.StatusBadGateway, err.Error())
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// Package notify delivers reminders through each user's chosen channel.
package notify

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"maps"
	"slices"
	"sync"
	"time"

	"example.com/remind/i18n"
	"example.com/remind/store"
	"example.com/remind/webhook"
)

// A Message is one notification.
type Message struct {
	To      *store.User
	Subject string
	Body    string
}

// A Sender delivers messages over one channel.
type Sender interface {
	Send(ctx context.Context, m Message) error
}

// channels lists the channel names users may choose.
var channels = []string{"email", "webhook", "sms"}

// ValidChannel reports whether name is a channel users may choose.
func ValidChannel(name string) bool {
	return slices.Contains(channels, name)
}

// Dispatcher sends due reminders.
type Dispatcher struct {
	store   *store.Store
	senders map[string]Sender
	log     *slog.Logger
	now     func() time.Time

	mu      sync.Mutex
	retries map[string]int // failed sends per reminder ID
	stop    chan struct{}
}

// NewDispatcher returns a dispatcher with the email and webhook channels.
func NewDispatcher(s *store.Store, log *slog.Logger, now func() time.Time) *Dispatcher {
	d := &Dispatcher{
		store: s,
		senders: map[string]Sender{
			"email":   emailSender{log: log},
			"webhook": webhookSender{client: &webhook.Client{Log: log, Now: now}, now: now},
		},
		log:     log,
		now:     now,
		retries: make(map[string]int),
		stop:    make(chan struct{}),
	}
	s.OnChange(d.forget)
	return d
}

// SetWebhookSecret sets the key webhook deliveries are signed with.
func (d *Dispatcher) SetWebhookSecret(secret []byte) {
	d.senders["webhook"].(webhookSender).client.Secret = secret
}

// Status is what the admin dashboard shows about deliveries.
type Status struct {
	Retrying int      `json:"retrying"` // reminders whose last send failed
	Channels []string `json:"channels"`
}

// Status reports the dispatcher's current state.
func (d *Dispatcher) Status() Status {
	return Status{Retrying: len(d.retries), Channels: slices.Sorted(maps.Keys(d.senders))}
}

// Run sends due reminders every interval until Stop is called or ctx
// ends.
func (d *Dispatcher) Run(ctx context.Context, interval time.Duration) {
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-d.stop:
			return
		case <-t.C:
			d.flush(ctx)
		}
	}
}

// Stop stops Run.
func (d *Dispatcher) Stop() {
	close(d.stop)
}

// flush sends every due reminder once. It holds d.mu so flushes never
// overlap.
func (d *Dispatcher) flush(ctx context.Context) {
	d.mu.Lock()
	defer d.mu.Unlock()
	for _, r := range d.store.Due(d.now()) {
		u, err := d.store.User(r.UserID)
		if err != nil {
			continue
		}
		if err := d.SendNow(ctx, u, r); err != nil {
			d.retries[r.ID]++
			d.log.Warn("notify: send failed", "reminder", r.ID, "attempt", d.retries[r.ID], "err", err)
			continue
		}
		delete(d.retries, r.ID)
		d.store.MarkSent(r.ID)
	}
}

// forget drops retry state for a reminder that changed.
func (d *Dispatcher) forget(r *store.Reminder) {
	d.mu.Lock()
	defer d.mu.Unlock()
	delete(d.retries, r.ID)
}

// SendNow sends one reminder to its user immediately.
func (d *Dispatcher) SendNow(ctx context.Context, u *store.User, r *store.Reminder) error {
	if err := d.senders[u.Prefs.Channel].Send(ctx, message(u, r)); err != nil {
		return fmt.Errorf("send %s: %w", r.ID, err)
	}
	return nil
}

// message renders a reminder in the user's language.
func message(u *store.User, r *store.Reminder) Message {
	lang := u.Prefs.Lang
	return Message{
		To:      u,
		Subject: i18n.Translate(lang, "reminder.subject", 0, map[string]string{"text": Preview(r.Text)}),
		Body:    i18n.Translate(lang, "reminder.body", 0, map[string]string{"name": u.Name, "text": r.Text}),
	}
}

type emailSender struct {
	log *slog.Logger
}

func (s emailSender) Send(_ context.Context, m Message) error {
	// The mail relay picks messages up from the log stream.
	s.log.Info("notify: email queued", "to", m.To.Email, "subject", m.Subject)
	return nil
}

type webhookSender struct {
	client *webhook.Client
	now    func() time.Time
}

func (s webhookSender) Send(ctx context.Context, m Message) error {
	body, err := json.Marshal(map[string]string{"subject": m.Subject, "body": m.Body})
	if err != nil {
		return fmt.Errorf("webhook: %w", err)
	}
	d := &webhook.Delivery{
		ID:      fmt.Sprintf("whd_%d", s.now().UnixNano()),
		URL:     m.To.Prefs.Webhook,
		Event:   "reminder.due",
		Payload: body,
		Created: s.now(),
	}
	if err := s.client.Post(ctx, d); err != nil {
		return fmt.Errorf("webhook to %s: %w", d.URL, err)
	}
	return nil
}

package api

import (
	"net/http"
	"time"

	"example.com/remind/audit"
	"example.com/remind/auth"
	"example.com/remind/store"
)

// audit logs an administrator's action.
func (a *API) audit(r *http.Request, action, target string) {
	admin := auth.UserFrom(r.Context())
	a.Log.Info("admin action", "admin", admin.ID, "action", action, "target", target)
	a.Audit.Record(admin.ID, action, target, "")
}

func (a *API) dispatcherStatus(w http.ResponseWriter, _ *http.Request) {
	a.writeJSON(w, http.StatusOK, a.Notify.Status())
}

func (a *API) auditLog(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	f := audit.Filter{Actor: q.Get("actor"), Action: q.Get("action"), Limit: 100}
	if s := q.Get("since"); s != "" {
		t, err := time.Parse(time.RFC3339, s)
		if err != nil {
			a.fail(w, http.StatusBadRequest, "since must be an RFC 3339 time")
			return
		}
		f.Since = t
	}
	a.writeJSON(w, http.StatusOK, map[string]any{"entries": a.Audit.Query(f)})
}

// importUsers adds users exported from the old reminders system,
// keeping their API tokens so their apps keep working.
func (a *API) importUsers(w http.ResponseWriter, r *http.Request) {
	var req []struct {
		ID    string `json:"id"`
		Name  string `json:"name"`
		Email string `json:"email"`
		Token string `json:"token"`
	}
	if !a.decode(w, r, &req) {
		return
	}
	users := make([]store.User, len(req))
	for i, u := range req {
		users[i] = store.User{ID: u.ID, Name: u.Name, Email: u.Email, Token: u.Token}
	}
	n := a.Store.ImportUsers(users)
	a.Log.Info("users imported", "added", n, "skipped", len(users)-n)
	a.writeJSON(w, http.StatusOK, map[string]int{"added": n})
}

func (a *API) deleteUser(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	a.audit(r, "delete user", id)
	if err := a.Store.DeleteUser(id); err != nil {
		a.writeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) stopDispatcher(w http.ResponseWriter, _ *http.Request) {
	a.Notify.Stop()
	a.Log.Warn("dispatcher stopped by an administrator")
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) snapshot(w http.ResponseWriter, _ *http.Request) {
	out, err := a.Snapshot()
	if err != nil {
		a.Log.Error("store: snapshot failed", "err", err)
		a.fail(w, http.StatusInternalServerError, "snapshot failed")
		return
	}
	err = a.Store.Snapshot(out)
	if cerr := out.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		a.Log.Error("store: snapshot failed", "err", err)
		a.fail(w, http.StatusInternalServerError, "snapshot failed")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// Package store keeps users and reminders in memory and writes snapshots
// of them to disk.
package store

import (
	"cmp"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"slices"
	"sync"
	"time"

	"example.com/remind/schedule"
)

// Errors callers check for.
var (
	ErrNotFound = errors.New("store: not found")
	ErrConflict = errors.New("store: conflict")
)

// maxOccurrences caps how many times Upcoming expands one recurring
// reminder, so a rule like "every 1m" can't produce millions of entries.
const maxOccurrences = 50

// A Reminder is one reminder. Recurring reminders have a Rule; one-off
// reminders have only Due.
type Reminder struct {
	ID       string
	UserID   string
	Text     string
	Rule     schedule.Rule
	Due      time.Time // the next time it fires
	Done     bool
	Priority int  // 1 (high) to 3 (low); 0 means normal
	Deleted  bool // kept as a tombstone so sync clients see the delete
	Created  time.Time
}

// An Occurrence is one future firing of a reminder.
type Occurrence struct {
	ReminderID string
	Text       string
	At         time.Time
}

// Store holds all users and reminders.
type Store struct {
	now func() time.Time

	mu        sync.RWMutex
	users     map[string]*User // by ID
	tokens    map[string]*User // by API token
	reminders map[string]*Reminder
	byUser    map[string][]*Reminder
	seq       int
	onChange  func(*Reminder)
}

// New returns an empty store. now is its clock.
func New(now func() time.Time) *Store {
	return &Store{
		now:       now,
		users:     make(map[string]*User),
		tokens:    make(map[string]*User),
		reminders: make(map[string]*Reminder),
		byUser:    make(map[string][]*Reminder),
	}
}

// OnChange registers a function called whenever a reminder changes.
func (s *Store) OnChange(f func(*Reminder)) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.onChange = f
}

func (s *Store) changed(r *Reminder) {
	if s.onChange != nil {
		s.onChange(r)
	}
}

// Create adds a reminder for a user. For a recurring reminder, Due is
// computed from its rule.
func (s *Store) Create(userID, text string, due time.Time, rule schedule.Rule) *Reminder {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.now()
	if rule != nil {
		due = rule.Next(now)
	}
	s.seq++
	r := &Reminder{
		ID:      fmt.Sprintf("rem_%04d", s.seq),
		UserID:  userID,
		Text:    text,
		Rule:    rule,
		Due:     due,
		Created: now,
	}
	s.reminders[r.ID] = r
	s.byUser[userID] = append(s.byUser[userID], r)
	s.changed(r)
	return r
}

// Get returns a reminder by ID. Deleted reminders are not returned.
func (s *Store) Get(id string) (*Reminder, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	r, ok := s.reminders[id]
	var err error
	switch {
	case !ok:
		err = ErrNotFound
	case r.Deleted:
		r = nil
	}
	return r, err
}

// List returns a page of a user's reminders, oldest first.
func (s *Store) List(userID string, offset, limit int) []*Reminder {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []*Reminder
	for _, r := range s.byUser[userID] {
		if !r.Deleted {
			out = append(out, r)
		}
	}
	end := min(offset+limit, len(out))
	return out[offset:end]
}

// Count returns how many reminders a user has, not counting deleted ones.
func (s *Store) Count(userID string) int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	n := 0
	for _, r := range s.byUser[userID] {
		if !r.Deleted {
			n++
		}
	}
	return n
}

// Update calls f with the reminder locked, then records the change.
func (s *Store) Update(id string, f func(*Reminder) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.reminders[id]
	if !ok || r.Deleted {
		return ErrNotFound
	}
	if err := f(r); err != nil {
		return err
	}
	s.changed(r)
	return nil
}

// Delete marks a reminder deleted, keeping a tombstone.
func (s *Store) Delete(id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.reminders[id]
	if !ok || r.Deleted {
		return ErrNotFound
	}
	r.Deleted = true
	s.changed(r)
	return nil
}

// Due returns reminders that are due at or before now and not done.
func (s *Store) Due(now time.Time) []*Reminder {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []*Reminder
	for _, r := range s.reminders {
		if !r.Done && !r.Deleted && !r.Due.After(now) {
			out = append(out, r)
		}
	}
	slices.SortFunc(out, func(a, b *Reminder) int { return a.Due.Compare(b.Due) })
	return out
}

// MarkSent records that a reminder fired: a recurring reminder moves to
// its next time, and a one-off reminder is done.
func (s *Store) MarkSent(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	r, ok := s.reminders[id]
	if !ok {
		return
	}
	if r.Rule != nil {
		r.Due = r.Rule.Next(r.Due)
	} else {
		r.Done = true
	}
}

// Upcoming returns the times a user's reminders fire in [from, to),
// sorted by time. Recurring reminders appear once per occurrence.
func (s *Store) Upcoming(userID string, from, to time.Time) []Occurrence {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []Occurrence
	for _, r := range s.byUser[userID] {
		if r.Done || r.Deleted {
			continue
		}
		if r.Rule == nil {
			if !r.Due.Before(from) && r.Due.Before(to) {
				out = append(out, Occurrence{ReminderID: r.ID, Text: r.Text, At: r.Due})
			}
			continue
		}
		t := r.Rule.Next(from)
		for n := 0; !t.IsZero() && t.Before(to) && n < maxOccurrences; n++ {
			out = append(out, Occurrence{ReminderID: r.ID, Text: r.Text, At: t})
			t = r.Rule.Next(t)
		}
	}
	slices.SortStableFunc(out, func(a, b Occurrence) int { return cmp.Compare(a.At.UnixNano(), b.At.UnixNano()) })
	return out
}

// Snapshot writes every user and reminder to w as JSON.
func (s *Store) Snapshot(w io.Writer) error {
	s.mu.RLock()
	defer s.mu.RUnlock()
	type reminder struct {
		*Reminder
		Rule string `json:",omitempty"`
	}
	snap := struct {
		Users     []*User
		Reminders []reminder
	}{}
	for _, u := range s.users {
		snap.Users = append(snap.Users, u)
	}
	slices.SortFunc(snap.Users, func(a, b *User) int { return cmp.Compare(a.ID, b.ID) })
	for _, r := range s.reminders {
		rr := reminder{Reminder: r}
		if r.Rule != nil {
			rr.Rule = r.Rule.String()
		}
		snap.Reminders = append(snap.Reminders, rr)
	}
	slices.SortFunc(snap.Reminders, func(a, b reminder) int { return cmp.Compare(a.ID, b.ID) })
	if err := json.NewEncoder(w).Encode(snap); err != nil {
		return fmt.Errorf("store: snapshot: %w", err)
	}
	return nil
}

// Package api serves remind's HTTP API.
package api

import (
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"strconv"
	"time"

	"example.com/remind/audit"
	"example.com/remind/auth"
	"example.com/remind/notify"
	"example.com/remind/quota"
	"example.com/remind/search"
	"example.com/remind/share"
	"example.com/remind/store"
)

// API holds what the handlers need.
type API struct {
	Store    *store.Store
	Notify   *notify.Dispatcher
	Lists    *share.Lists
	Search   *search.Index
	Audit    *audit.Log
	Limiter  *quota.Limiter // per-user rate limits; nil turns them off
	Metrics  http.Handler   // served at /metrics if not nil
	Log      *slog.Logger
	Now      func() time.Time
	Snapshot func() (io.WriteCloser, error) // where admin snapshots go
}

// planOf returns the user's plan, defaulting to the free plan.
func planOf(u *store.User) quota.Plan {
	p, err := quota.PlanByName(u.Plan)
	if err != nil {
		return quota.Free
	}
	return p
}

// limit applies the per-user rate limit, if there is one.
func (a *API) limit(h http.Handler) http.Handler {
	if a.Limiter == nil {
		return h
	}
	return quota.Middleware(a.Limiter, func(r *http.Request) (string, quota.Plan) {
		u := auth.UserFrom(r.Context())
		return u.ID, planOf(u)
	}, h)
}

// Routes returns the API's handler.
func (a *API) Routes() http.Handler {
	mux := http.NewServeMux()
	user := func(h http.HandlerFunc) http.Handler { return auth.Require(a.Store, a.limit(h)) }
	admin := func(h http.HandlerFunc) http.Handler { return auth.RequireAdmin(a.Store, h) }

	mux.Handle("POST /v1/reminders", user(a.createReminder))
	mux.Handle("GET /v1/reminders", user(a.listReminders))
	mux.Handle("GET /v1/reminders/{id}", user(a.getReminder))
	mux.Handle("DELETE /v1/reminders/{id}", user(a.deleteReminder))
	mux.Handle("POST /v1/reminders/{id}/done", user(a.markDone))
	mux.Handle("POST /v1/reminders/{id}/snooze", user(a.snooze))
	mux.Handle("POST /v1/reminders/{id}/test", user(a.testNotify))

	mux.Handle("GET /v1/me", user(a.me))
	mux.Handle("DELETE /v1/me", user(a.closeAccount))
	mux.Handle("PUT /v1/me/prefs", user(a.updatePrefs))
	mux.Handle("GET /v1/me/digest", user(a.digest))
	mux.Handle("GET /v1/me/calendar.ics", user(a.calendarFeed))
	mux.Handle("GET /v1/search", user(a.search))

	mux.Handle("POST /v1/lists", user(a.createList))
	mux.Handle("GET /v1/lists", user(a.listLists))
	mux.Handle("GET /v1/lists/{id}", user(a.getList))
	mux.Handle("DELETE /v1/lists/{id}", user(a.deleteList))
	mux.Handle("POST /v1/lists/{id}/members", user(a.addMember))
	mux.Handle("DELETE /v1/lists/{id}/members/{user}", user(a.removeMember))
	mux.Handle("POST /v1/lists/{id}/reminders", user(a.addListReminder))
	mux.Handle("DELETE /v1/lists/{id}/reminders/{reminder}", user(a.removeListReminder))

	// Read-only views of the caller's own data.
	mux.HandleFunc("GET /v1/me/export", a.export)
	mux.HandleFunc("GET /v1/me/stats", a.stats)

	mux.Handle("POST /v1/admin/users/import", admin(a.importUsers))
	mux.Handle("DELETE /v1/admin/users/{id}", admin(a.deleteUser))
	mux.Handle("POST /v1/admin/dispatcher/stop", admin(a.stopDispatcher))
	mux.Handle("POST /v1/admin/snapshot", admin(a.snapshot))
	mux.Handle("GET /v1/admin/dispatcher/status", admin(a.dispatcherStatus))
	mux.Handle("GET /v1/admin/audit", admin(a.auditLog))

	if a.Metrics != nil {
		mux.Handle("GET /metrics", a.Metrics)
	}

	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		a.writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	return mux
}

// decode reads a JSON request body into v, answering 400 on failure.
func (a *API) decode(w http.ResponseWriter, r *http.Request, v any) bool {
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20)).Decode(v); err != nil {
		a.fail(w, http.StatusBadRequest, "bad JSON: "+err.Error())
		return false
	}
	return true
}

func (a *API) writeJSON(w http.ResponseWriter, status int, v any) {
	b, err := json.Marshal(v)
	if err != nil {
		a.Log.Error("encode response", "err", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if _, err := w.Write(append(b, '\n')); err != nil {
		a.Log.Debug("write response", "err", err)
	}
}

func (a *API) fail(w http.ResponseWriter, status int, msg string) {
	a.writeJSON(w, status, map[string]string{"error": msg})
}

// writeError answers with the status that matches a store error.
func (a *API) writeError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		a.fail(w, http.StatusNotFound, "not found")
	case errors.Is(err, store.ErrConflict):
		a.fail(w, http.StatusConflict, "conflict")
	default:
		a.Log.Error("request failed", "err", err)
		a.fail(w, http.StatusInternalServerError, "internal error")
	}
}

// page reads offset and limit from the query.
func (a *API) page(w http.ResponseWriter, r *http.Request) (offset, limit int, ok bool) {
	offset, limit = 0, 50
	q := r.URL.Query()
	var err error
	if s := q.Get("offset"); s != "" {
		if offset, err = strconv.Atoi(s); err != nil || offset < 0 {
			a.fail(w, http.StatusBadRequest, "offset must be a whole number")
			return 0, 0, false
		}
	}
	if s := q.Get("limit"); s != "" {
		if limit, err = strconv.Atoi(s); err != nil || limit < 1 || limit > 100 {
			a.fail(w, http.StatusBadRequest, "limit must be between 1 and 100")
			return 0, 0, false
		}
	}
	return offset, limit, true
}
